calc.mjs.text:
// EU Data Act (Regulation (EU) 2023/2854) applicability check from a business's role, size and EU
// reach. Pure functions, no I/O. Bad input is rejected with a message, never clamped. Encodes the
// micro and small enterprise exemptions (Art 7 for Chapter II, Art 14 for business-to-government
// requests) on the Recommendation 2003/361/EC ceilings, and the dates in Art 50, Art 3(1), Art 13
// and Art 29. It does not model partner-enterprise proportional size; the answer is a first read.

export const ROLES = [
  { id: "none", label: "None of the roles below", chapter: null },
  { id: "manufacturer", label: "Manufacturer of a connected product (a product that gets or generates data about its use and can send it)", chapter: "II" },
  { id: "service", label: "Provider of a related service (software or app connected to the product that affects what it does)", chapter: "II" },
  { id: "holder", label: "Data holder (you hold or control data generated by a customer's connected product and can make it available)", chapter: "II" },
  { id: "cloud", label: "Provider of a data processing service (cloud, SaaS, IaaS, PaaS or edge service customers can switch away from)", chapter: "VI" },
  { id: "recipient", label: "Third party that asks a data holder for a user's connected-product data", chapter: "III" },
];

export const SIZES = ["micro", "small", "notsmall"];
export const SIZE_LABEL = { micro: "microenterprise", small: "small enterprise", notsmall: "medium or large enterprise" };

// Recommendation 2003/361/EC Article 2: micro under 10 people and EUR 2M turnover or balance sheet;
// small under 50 people and EUR 10M. Whole-group figures; linked enterprises count in full.
export function sizeClass(staff, turnoverM, balanceM) {
  if (staff < 10 && (turnoverM <= 2 || balanceM <= 2)) return "micro";
  if (staff < 50 && (turnoverM <= 10 || balanceM <= 10)) return "small";
  return "notsmall";
}

function num(raw, name, errors) {
  const s = raw === undefined || raw === null ? "" : String(raw).trim().replace(/[€,\s]/g, "");
  if (s === "") { errors.push(`${name} is required (enter 0 if none).`); return 0; }
  const v = Number(s);
  if (!Number.isFinite(v)) { errors.push(`${name} must be a number.`); return 0; }
  if (v < 0) { errors.push(`${name} cannot be negative.`); return 0; }
  return v;
}

const yes = (v) => Boolean(v) && v !== "0" && v !== "no";

export function parse(input) {
  const errors = [];
  const i = input || {};
  const role = ROLES.find((r) => r.id === i.role);
  if (!role) errors.push("Choose your role.");
  const staff = num(i.staff, "Staff (people employed, whole group)", errors);
  const turnover = num(i.turnover, "Annual turnover (EUR millions)", errors);
  const balance = num(i.balance, "Annual balance sheet total (EUR millions)", errors);
  const eu = ["yes", "no", "unsure"].includes(i.eu) ? i.eu : "yes";
  return { errors, role, staff, turnover, balance, eu, partner: yes(i.partner), subcontract: yes(i.subcontract) };
}

// One decision. `size` is the size class the group is treated as having.
export function classify({ role, size, eu = "yes", partner = false, subcontract = false }) {
  if (eu === "no") {
    return { status: "out", via: "Art 1(3)", reason: "The Regulation reaches products placed on the Union market, users in the Union and data recipients there, wherever you are established. Without any of those, it does not apply directly." };
  }
  if (!role || role.chapter === null) {
    return { status: "out", via: "Art 1, Art 2", reason: "None of the roles the Regulation addresses describes you, so it does not apply directly." };
  }
  if (role.chapter === "VI") {
    return { status: "in", via: "Art 23 to 31", reason: "The switching duties for data processing services have no size exemption. Small providers are covered; Article 31 only eases some duties for custom-built services and non-production versions." };
  }
  if (role.chapter === "III") {
    return { status: "in", via: "Art 5, Art 6", reason: "Third parties receiving a user's data carry the conditions in Article 6 whatever their size. A gatekeeper under the Digital Markets Act cannot be one (Art 5(3))." };
  }
  const small = size === "micro" || size === "small";
  if (small && !partner && !subcontract) {
    return { status: "exempt-small", via: "Art 7", reason: "Micro and small enterprises are exempt from the Chapter II data-access duties for the connected products they make and services they provide, provided they have no larger partner or linked enterprise and are not subcontracted to make or design the product for one." };
  }
  if (small) {
    return { status: "in", via: `Art 2, Art 7, ${role.chapter === "II" ? "Art 3 to 5" : ""}`.replace(/, $/, ""), reason: partner ? "A larger partner or linked enterprise removes the small-enterprise exemption: size is judged on the group." : "Being subcontracted to make or design the product or service for a larger company removes the small-enterprise exemption." };
  }
  return { status: "in", via: "Art 3 to 5", reason: "You are not a micro or small enterprise, so the Chapter II duties on connected-product data apply to you." };
}

const OBLIGATIONS = {
  manufacturer: [
    "Design connected products placed on the market after 12 September 2026 so the user can reach the product data and related-service data directly, easily and securely, free of charge, in a structured, commonly used, machine-readable format (Art 3(1)).",
    "Before a sale, rental or lease contract, tell the user what data the product generates, how much, how often, where it is stored, how to access, retrieve or delete it, and who the data holder is (Art 3(2)).",
    "On the user's request, make readily available data available to the user, and to a third party they name, without undue delay and free of charge to the user (Art 4, Art 5).",
    "Keep trade secrets protected through agreed measures; you may refuse only where serious damage is likely and you tell the authority (Art 4(6), Art 4(8)).",
    "Do not use the user's non-personal data to learn about their economic position or to undercut them (Art 4(13)).",
  ],
  service: [
    "Before a contract, give the user the information on the data the related service generates and how to access it (Art 3(3)).",
    "Make the data available to the user, and to a third party they name, on request, free of charge to the user (Art 4, Art 5).",
    "Use readily available non-personal data from the user only as the contract with the user allows (Art 4(13)).",
  ],
  holder: [
    "Make readily available data available to the user on request, free of charge, and to a third party the user names (Art 4, Art 5).",
    "Any compensation asked from a business data recipient must be non-discriminatory and reasonable, and for small and micro recipients not above the cost of making the data available (Art 8, Art 9).",
    "Terms on access, use and liability for the data must be fair, reasonable and non-discriminatory (Art 8). Unilateral terms that are unfair to the other business are not binding (Art 13).",
    "Keep trade secrets protected by agreed measures, and settle disputes through a certified dispute settlement body if the parties choose to (Art 4, Art 10).",
    "Unless you are a micro or small enterprise, provide data to public sector bodies on a documented exceptional need such as a public emergency (Art 14 to 22).",
  ],
  cloud: [
    "Put in the contract the customer's rights to switch to another provider or to on-premises, with a maximum notice period of two months and a transition of up to 30 days (Art 25).",
    "Support the switch, keep service continuity and give exportable data and digital assets in a structured, commonly used, machine-readable format (Art 23, Art 25, Art 30).",
    "Switching charges: reduced until 12 January 2027, and none after that date, though cost-based data egress charges are allowed until then (Art 29).",
    "Publish information about your data location, and take the technical and organisational measures against unlawful non-personal data access by non-EU governments (Art 28, Art 32).",
    "Check the interoperability, open-interface and exit specifications (Art 30, Art 35).",
  ],
  recipient: [
    "Use the data only for the purposes and conditions agreed with the user, and delete it when it is no longer needed (Art 6(1)).",
    "Do not coerce, deceive or manipulate the user, and do not use the data for profiling unless it is necessary for the service the user asked for (Art 6(2)).",
    "Do not make the data available to another third party unless that is needed for the service, and do not use it to build a competing connected product (Art 6(2)).",
    "Apply any agreed trade-secret measures (Art 6(1)).",
  ],
};

export function compute(input) {
  const p = parse(input);
  if (p.errors.length) return { errors: p.errors };
  const size = sizeClass(p.staff, p.turnover, p.balance);
  const base = { role: p.role, eu: p.eu, partner: p.partner, subcontract: p.subcontract };
  const verdict = classify({ ...base, size });
  const ladder = SIZES.map((s) => ({ size: s, ...classify({ ...base, size: s }) }));
  const findings = [];
  const inScope = verdict.status === "in";
  if (inScope) {
    findings.push({ severity: "high", title: `Likely in scope (${verdict.via}). The Regulation has applied since 12 September 2025.` });
    if (p.role.id === "manufacturer") findings.push({ severity: "medium", title: "The access-by-design duty in Art 3(1) applies to connected products placed on the market after 12 September 2026. Products already on the market still carry the Art 4 and Art 5 request duties." });
    findings.push({ severity: "medium", title: "Enforcement and penalties are set by each Member State's competent authorities (Art 37, Art 40). Personal data stays under the GDPR; the Data Act does not replace it." });
    if (p.role.chapter === "II") findings.push({ severity: "info", title: "Contract terms imposed on another business about data access are tested for unfairness (Art 13). From 12 September 2027 that also reaches older indefinite or long-running contracts." });
  } else if (verdict.status === "exempt-small") {
    findings.push({ severity: "medium", title: "Exempt from the Chapter II duties as a micro or small enterprise (Art 7). The exemption is judged on the whole group and is lost with a larger partner or linked enterprise. A medium enterprise keeps it for about a year after growing past small, so recheck when you grow." });
    findings.push({ severity: "info", title: "Customers and larger partners may still ask for data access by contract. If another company makes your product data available, that company has the duty." });
  } else {
    findings.push({ severity: "info", title: "Not in scope directly on these answers." });
  }
  if (p.eu === "unsure") findings.push({ severity: "medium", title: "You answered unsure on whether you reach the Union. Settle that first: it decides whether the Regulation applies at all." });
  if ((p.partner || p.subcontract) && p.role && p.role.chapter === "II" && (size === "micro" || size === "small")) findings.push({ severity: "medium", title: "You marked a larger partner, linked enterprise or subcontracting. That removes the Art 7 exemption even at this size." });
  findings.push({ severity: "info", title: "Partner-enterprise proportional size rules are not applied here beyond the yes or no answer above. Enter whole-group figures." });
  return {
    errors: [], size, sizeLabel: SIZE_LABEL[size], role: p.role, verdict, ladder, findings,
    obligations: inScope ? OBLIGATIONS[p.role.id] : [],
    input: { staff: p.staff, turnover: p.turnover, balance: p.balance, eu: p.eu, partner: p.partner, subcontract: p.subcontract },
  };
}

export const SAMPLE = { role: "manufacturer", staff: "35", turnover: "6", balance: "4", eu: "yes", partner: "", subcontract: "" };

const STATUS_TEXT = { in: "in scope", "exempt-small": "exempt as a micro or small enterprise", out: "not in scope directly" };

export function summaryText(r) {
  const v = r.verdict;
  const lines = [
    "EU Data Act check (first read, not legal advice)",
    `Role: ${r.role.label}`,
    `Size on whole-group figures: ${r.sizeLabel} (${r.input.staff} people, EUR ${r.input.turnover}M turnover, EUR ${r.input.balance}M balance sheet)`,
    `Result: ${STATUS_TEXT[v.status]} [${v.via}]`,
    v.reason,
    "",
    "Same business at each size class:",
    ...r.ladder.map((l) => `  ${SIZE_LABEL[l.size]}: ${STATUS_TEXT[l.status]}`),
  ];
  if (r.obligations.length) lines.push("", "Main duties:", ...r.obligations.map((o) => `  - ${o}`));
  lines.push("", "The Regulation is enforced by national authorities and some dates depend on when a product was placed on the market. Confirm with your authority or counsel.");
  return lines.join("\n");
}

export function ladderCsv(r) {
  return ["size,status,basis", ...r.ladder.map((l) => [SIZE_LABEL[l.size], l.status, l.via].map((c) => `"${String(c).replace(/"/g, '""')}"`).join(","))].join("\n");
}

